import json,re,hashlib,xml.etree.ElementTree as ET
from html.parser import HTMLParser
from pathlib import Path
class Text(HTMLParser):
 def __init__(self): super().__init__(convert_charrefs=True); self.parts=[]
 def handle_data(self,s): self.parts.append(s)
 def handle_starttag(self,t,a):
  if t in ('p','br','div','li','tr'): self.parts.append(' ')
 def handle_endtag(self,t):
  if t in ('p','div','li','tr'): self.parts.append(' ')
def plain(s):
 p=Text();p.feed(s);return ' '.join(''.join(p.parts).split())
s=json.loads(Path('source.json').read_text());a=json.loads(Path('answer.json').read_text());assert len(s)==len(a)==2
fields={'code_id','source_id','source_sha256','number','proposed_xml','reason','review_notes','status','change_type','repeal_policy_id','repeal_scope','substantive_impact'}
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
for src,d in zip(s,a):
 assert fields<=d.keys()
 for k in ['code_id','source_id','source_sha256','number']:assert src[k]==d[k],k
 assert hashlib.sha256(src['source_xml'].encode()).hexdigest()==src['source_sha256']
 assert src['previous_draft']['source_sha256']==src['source_sha256']
 assert d['status']=='rewrite_draft' and d['change_type']=='full_repeal'
 assert len(d['repeal_scope'])>=30
 assert d['repeal_policy_id']=='editorial_direction_2026_10_19'
 assert plain(d['proposed_xml']).startswith(('Le présent article est abrogé','Abrogé'))
 root=ET.fromstring('<root>'+d['proposed_xml']+'</root>')
 for e in root.iter():
  if e is root:continue
  assert e.tag in allowed
  for k,v in e.attrib.items():assert k in ('rowspan','colspan') and re.fullmatch(r'\\d+',v)
 im=d['substantive_impact'];assert im['version']==1
 for k in ['assessment','scope_limitations','new_burdens_review']:assert len(im[k])>=40
 assert len(d.get('benefit_review',''))>=100
 for e in im['effects']:
  assert set(e)=={'kind','measure_id','description','before','after','unit','affected_population','conditions_and_transition','replacement_or_new_burdens','source_quote','proposed_quote'}
  assert re.fullmatch(r'[a-z][a-z0-9-]{5,95}',e['measure_id'])
  for k,text in [('source_quote',plain(src['source_xml'])),('proposed_quote',plain(d['proposed_xml']))]:
   assert len(e[k])>=12 and e[k] in text,(d['number'],k,e[k])
 print(d['number'],': identité, empreinte source, XML, champs et',len(im['effects']),'citations avant/après vérifiés')
print('Sources et notes intactes ; aucun tableau ni compagnon dans les deux sources.')
print('Taille answer.json :',Path('answer.json').stat().st_size,'octets')
PY"

